diff --git a/lib/src/cli/agent_cli_waiting.dart b/lib/src/cli/agent_cli_waiting.dart
index 09ab62a34b..de44631edd 100644
--- a/lib/src/cli/agent_cli_waiting.dart
+++ b/lib/src/cli/agent_cli_waiting.dart
@@ -139,6 +139,17 @@ final class _WaitingCoordinator {
   /// timeout guess (issue #2266 AC3).
   bool _lockExclusiveProven = false;

+  /// Settled ids whose remove landed before their add could claim the
+  /// registry lock (issue #2350): the lock queues whoever claims FIRST,
+  /// it cannot reorder claims — under load the add's pre-claim fs work
+  /// can lose the 10ms settle lag, the remove lands on an empty
+  /// manifest, and the late add resurrects an exited job as running.
+  /// A settle remembers its id here (synchronously, before any await)
+  /// and the add checks the tombstone inside the locked mutate: a late
+  /// add for a settled id is dropped. Same-isolate bookkeeping — the
+  /// cross-process RMW race stays under the fs lock.
+  final _settledBeforeAdd = <String>{};
+
   /// The latest exclusive-create refusal, retained until the immediately
   /// following occupancy probe distinguishes contention from a broken fs.
   FileError? _lastRegistryLockClaimError;
@@ -595,6 +606,13 @@ final class _WaitingCoordinator {
     Future<String?> Function()? pidStartProbe,
   }) async {
     await _mutateRegistry((entries) async {
+      // A settle that already landed for this id (its remove won the
+      // claim race — issue #2350) drops this late add: without the check
+      // the add resurrects an exited job as running until the next boot.
+      // NOT consumed: adoption fires an unawaited add chain of its own
+      // (onStart), so duplicate adds for one settled id are normal — the
+      // first consumer must not un-protect the second.
+      if (_settledBeforeAdd.contains(id)) return entries;
       // The probe runs INSIDE the critical section (issue #2275): run
       // outside, its async gap let a fast-settling job's remove land
       // first — the add then resurrected an EXITED job as running until
@@ -911,7 +929,13 @@ final class _WaitingCoordinator {
   /// surviving group members keyed by it. Verified-gone stops (and every
   /// natural settle) remove as before.
   Future<void> jobSettled(ShellJobEntry job) async {
-    if (!adoptedStopKeepsManifestRecord(job)) await _manifestRemove(job.id);
+    if (!adoptedStopKeepsManifestRecord(job)) {
+      // Remembered SYNCHRONOUSLY, before any await (issue #2350): this
+      // chain can outrun the still-unclaimed add — the tombstone is what
+      // makes the late add drop instead of resurrecting the exited job.
+      _settledBeforeAdd.add(job.id);
+      await _manifestRemove(job.id);
+    }
     await push();
   }

diff --git a/test/cli/agent_cli_waiting_fast_settle_test.dart b/test/cli/agent_cli_waiting_fast_settle_test.dart
index fc39ebc315..95388f025f 100644
--- a/test/cli/agent_cli_waiting_fast_settle_test.dart
+++ b/test/cli/agent_cli_waiting_fast_settle_test.dart
@@ -104,4 +104,40 @@ void main() {
     expect(entries.single['pidStart'], startTag);
     expect(entries.single['pid'], '4243');
   });
+
+  test(
+    'AC3: a remove that fully landed before its add claims drops the '
+    'late add — no ghost on the inverted claim order (issue #2350)',
+    () async {
+      final (cli, env, io, manifest) = await settleCli(
+        'ac3',
+        pidStart: (pid) async {
+          await Future<void>.delayed(const Duration(milliseconds: 100));
+          return 'slow probe';
+        },
+      );
+      final job = cli.shellJobsRegistryForTest.adoptRunningEntry(
+        id: 'sh-2350',
+        command: 'true',
+        pid: 4242,
+      );
+      // The registry lock queues whoever CLAIMS first — it cannot reorder
+      // claims. Under load jobStarted's pre-claim fs work loses the 10ms
+      // settle lag, the remove lands on an empty manifest, and the late
+      // add resurrects the exited job (2/2 CI runs, issue #2350). The
+      // deterministic extreme of that order: the settle chain runs to
+      // completion BEFORE the add fires at all. The settle tombstone is
+      // what makes the late add drop.
+      await cli.waitingJobSettledForTest(job);
+      await cli.waitingJobStartedForTest(job);
+
+      expect(
+        manifestEntries((await env.readTextFile(manifest)).valueOrNull),
+        isEmpty,
+        reason:
+            'a remove observed before its add must be remembered '
+            'so the late add drops',
+      );
+    },
+  );
 }

// The visible-waiting coordinator (issue #450): one aggregate over the two
// waiting horizons — session-scoped background shell jobs (process-local,
// [ShellJobRegistry]) and persistent self-wake timers
// ([ScheduledMessageQueue]) — pushed to the TUI waiting row on every
// waiter enter/leave (never polled per frame), a ~20-minute heartbeat
// while waiters exist, restart honesty for jobs lost across runs, and the
// headless semantics (`--wait-for-jobs` + the detach summary).
//
// Part of agent_cli.dart (same pattern as agent_cli_persist.dart): the
// state lives on this coordinator, not on [AgentCli], to keep the host
// class under the line gate.
part of 'agent_cli.dart';

/// One waiter-aggregate snapshot: what the agent is waiting for right now.
final class WaiterSnapshot {
